#!/usr/bin/env bash
# Detector `no-case-collision` for [R:case-collision], generated by relearn from the rule file.
# Edit the rule, never this script: `relearn verify` reports a hand edit.
# Engine: sibling-case. Event: Claude Code PreToolUse, on Write.
# Exit 2 blocks, and stderr is the reason Claude reads. Exit 0 allows.
# Any other exit is this script failing: reported, never a block.
set -uo pipefail
export LC_ALL=C

name='no-case-collision'
tag='R:case-collision'
message='On a case-insensitive filesystem the two names are one file, so this write would replace the existing one. Write into the existing file, or choose a name that differs by more than case.'
files_ere='((^|/).*$)'

fail() {
  printf '[%s] %s; the detector did not run.\n' "$name" "$1" >&2
  exit 1
}
command -v jq >/dev/null 2>&1 || fail "jq is not on PATH"

input="$(cat)"
tool_name="$(jq -r '.tool_name // ""' <<<"$input")" || fail "the payload is not JSON"
case "$tool_name" in Write) ;; *) exit 0 ;; esac
file_path="$(jq -r '.tool_input.file_path // ""' <<<"$input")" || fail "the payload has no readable file_path"
file_path="${file_path//\\//}"
[ -n "$file_path" ] || exit 0

# Scope: one ERE per list, compiled by relearn from the rule's globs.
printf '%s\n' "$file_path" | grep -qE -- "$files_ere"
case $? in 0) ;; 1) exit 0 ;; *) fail "grep could not read the files pattern" ;; esac

dir="$(dirname -- "$file_path")"
base="$(basename -- "$file_path")"
[ -d "$dir" ] || exit 0
lower() { printf '%s' "$1" | tr '[:upper:]' '[:lower:]'; }
base_lc="$(lower "$base")"
collision=""
for entry in "$dir"/* "$dir"/.[!.]* "$dir"/..?*; do
  [ -e "$entry" ] || continue
  sibling="${entry##*/}"
  # The exact name already exists: this write replaces that file, as intended.
  [ "$sibling" = "$base" ] && exit 0
  if [ -z "$collision" ] && [ "$(lower "$sibling")" = "$base_lc" ]; then
    collision="$sibling"
  fi
done
[ -n "$collision" ] || exit 0

{
  printf '[%s] %s: BLOCKED. %s differs only by case from the existing %s in %s. %s\n' "$tag" "$name" "$base" "$collision" "$dir" "$message"
} >&2
exit 2

